import{_ as r,o as e,c as o,ag as i}from"./chunks/framework.Aev9KvMf.js";const p=JSON.parse('{"title":"来源白名单增设第三级：权威医疗机构与认证医生","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0007-third-tier-sources.md","filePath":"project/adr/0007-third-tier-sources.md"}'),a={name:"project/adr/0007-third-tier-sources.md"};function s(l,t,n,c,_,d){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="来源白名单增设第三级-权威医疗机构与认证医生" tabindex="-1">来源白名单增设第三级：权威医疗机构与认证医生 <a class="header-anchor" href="#来源白名单增设第三级-权威医疗机构与认证医生" aria-label="Permalink to &quot;来源白名单增设第三级：权威医疗机构与认证医生&quot;">​</a></h1><p>用户计划在后续阶段引入第三方权威医院医生的科普内容，与 ADR 0002 的&quot;医院公众号一律不收&quot;冲突，故以本 ADR 取代该条。白名单改为三级：</p><ul><li><strong>一级</strong>：国务院部委及直属机构（卫健委、疾控局、标准委、市场监管总局等）。</li><li><strong>二级</strong>：官方指定专业机构（中国营养学会、中国疾控中心、中国消费者协会）。</li><li><strong>三级（新增，后置启用）</strong>：权威医疗机构（三甲医院等）的官方科普，以及经资质认证的医生个人科普。</li></ul><p>三级来源的收录护栏：</p><ol><li>资质必须可核验：机构实名、医生真实姓名 + 职称 + 所在机构，页面标注来源级别与作者。</li><li>以&quot;链接 + 摘要 + 标注&quot;为主，不整篇转载——医生科普享有著作权，与政府公文不同。</li><li>与一级来源冲突时，以一级来源为准，并显式标注分歧。</li><li>启用时点后置：待首批词条闭环（发布 → 被搜到 → 收到纠错）后再评估，遵守&quot;一次只扩一个域&quot;的纪律。</li></ol>',5)])])}const h=r(a,[["render",s]]);export{p as __pageData,h as default};
